INSERT INTO `projects` (`id`, `slug`, `name`, `type`, `classification`, `status`, `location`, `address`, `description`, `latitude`, `longitude`, `rera_number`, `rera_verified`, `price_label`, `starting_price`, `possession_label`, `cover_image`, `logo_image`, `brochure_path`, `sales_phone`, `sort_order`, `amenities`, `configs`, `images`, `specs`, `aerial_backdrop`, `created_at`, `updated_at`) VALUES (13, 'kedia-utsav', 'Kedia Utsav', 'Villas', 'Single-Family', 'completed', 'Ajmer Road', 'Ajmer Road, Jaipur, Rajasthan', 'शहर के बीचों बीच आपका घर। प्लॉट्स 28 लाख से शुरू केडिया उत्सव एक रेजिडेंशियल प्लॉटिंग स्कीम है, जो शहर के बीचों बीच है । केडिया उत्सव के शानदार कनेक्टिविटी जो की अजमेर हाईवे , कमला नेहरू नगर चोराडिया सिटी , गांधीपत और धावास से है। केडिया उत्सव विला टाइप प्लॉट्स थीम पर प्लैन्ड है। इस प्रोजेक्ट में ग्रैंड एंट्री गेट एवम ड्यूल एंट्री है , अंडर ग्राउंड इलेक्ट्रिसिटी , पानी इतियाद लाइंस , पार्क बच्चों और वयस्क के हिसांबसे , ओपन एमपीथिएटर , बढ़िया रोड्स , वाटर टैंक सोसायटी के लिए । प्रोजेक्ट में जेडीए द्वारा कैंप लग भग 28th जून 2022 से शुरू होगा । रजिस्ट्री का खर्चा बचेगा और पट्टा सीधे प्लॉट आवंटी की नाम निकलेगा। इस प्रोजेक्ट को शहर के बीचों बीच प्लान किया है। यह केडिया बिल्डर्स का भरोसा है जो कायम रहेगा । प्लॉट्स 28 लाख से शुरू । RERA', NULL, NULL, 'RAJ/P/2018/889', 0, 'Starting at ₹75.00 Lakh*', 7500000, 'Ready to Move', 'img/2022/06/WhatsApp-Image-2022-06-10-at-8.15.00-PM', 'img/2022/06/Utsav', 'docs/kedia-utsav-brochure.pdf', '+91 8302 500 500', 12, '[]', '[]', '[{"path":"img/2022/06/WhatsApp-Image-2022-06-10-at-8.15.01-PM","kind":"gallery","caption":"Kedia Utsav photo 1"},{"path":"img/2022/06/WhatsApp-Image-2022-06-10-at-8.15.02-PM","kind":"gallery","caption":"Kedia Utsav photo 2"},{"path":"img/2022/06/WhatsApp-Image-2022-06-10-at-8.15.03-PM","kind":"gallery","caption":"Kedia Utsav photo 3"},{"path":"img/2022/06/WhatsApp-Image-2022-06-10-at-8.15.00-PM","kind":"gallery","caption":"Kedia Utsav photo 4"}]', '[{"group":"Structure & Masonry","items":["Earthquake resistant RCC framed structure (Zone II compliant)","High-grade fly ash & red-clay modular brickwork","Waterproofing with crystalline membrane on roof & wet areas"]},{"group":"Flooring & Finishes","items":["Italian-inspired vitrified tiles (800x1600mm) in living & dining","Anti-skid matte ceramic tiles in balconies and bathrooms","Textured exterior weather-coat paint with architectural cornices"]},{"group":"Electrical & Tech","items":["Concealed copper wiring (Finolex / Havells) with modular switches","Provisions for split AC in all bedrooms and living salon","High-speed FTTH optical fiber conduits and EV charging point provision"]},{"group":"Sanitary & Plumbing","items":["Premium CP fittings (Kohler / Jaquar or equivalent)","Wall-hung EWCs with concealed soft-close cisterns","Dual-plumbing system for treated greywater garden flush"]}]', '/media/img/2025/04/DJI_0788-3-scaled-1920.webp', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
