-- -------------------------------------------------------------
-- Table structure for units
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `units`;
CREATE TABLE `units` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `unit_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tower_or_block` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Phase 1',
  `unit_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Villa',
  `configuration` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bedrooms` int NOT NULL DEFAULT '3',
  `bathrooms` int NOT NULL DEFAULT '3',
  `area_sqft` int NOT NULL DEFAULT '0',
  `area_sqyd` decimal(8,2) NOT NULL DEFAULT '0.00',
  `facing` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'East',
  `floor_level` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ground',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'available',
  `base_price` bigint NOT NULL DEFAULT '0',
  `development_charges` bigint NOT NULL DEFAULT '0',
  `club_membership` bigint NOT NULL DEFAULT '0',
  `parking_charges` bigint NOT NULL DEFAULT '0',
  `gst` bigint NOT NULL DEFAULT '0',
  `stamp_duty_registration` bigint NOT NULL DEFAULT '0',
  `total_price` bigint NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `specifications` json DEFAULT NULL,
  `possession` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `units_unit_code_unique` (`unit_code`),
  KEY `units_project_slug_index` (`project_slug`),
  KEY `units_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

