-- -------------------------------------------------------------
-- Table structure for bookings
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `bookings`;
CREATE TABLE `bookings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `booking_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_phone` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_pan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_aadhar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `booking_date` datetime NOT NULL,
  `token_amount_paid` bigint NOT NULL DEFAULT '100000',
  `total_unit_amount` bigint NOT NULL DEFAULT '0',
  `payment_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPI',
  `payment_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'confirmed',
  `payment_schedule` json DEFAULT NULL,
  `cost_breakdown` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bookings_booking_id_unique` (`booking_id`),
  KEY `bookings_unit_code_index` (`unit_code`),
  KEY `bookings_project_slug_index` (`project_slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `bookings` (`id`, `booking_id`, `unit_code`, `unit_number`, `project_slug`, `project_name`, `customer_name`, `customer_email`, `customer_phone`, `customer_pan`, `customer_aadhar`, `address`, `booking_date`, `token_amount_paid`, `total_unit_amount`, `payment_method`, `payment_reference`, `status`, `created_at`, `updated_at`) VALUES
