-- -------------------------------------------------------------
-- Table structure for site_visit_leads
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `site_visit_leads`;
CREATE TABLE `site_visit_leads` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `preferred_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preferred_time` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'website_modal',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new',
  `assigned_advisor` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Kedia Relationship Desk',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `site_visit_leads_lead_code_unique` (`lead_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

